// Экран листа: «Настройки» (08 § 7.23; В-28): Размер текста, Плотность, Тема — первыми; Возраст — поле числа и «Не указывать».
// Настройки — только на этом устройстве; изменение действует сразу; объявление — что изменилось. ПРОТОТИП.
(function () {
  const О = window.ОБЩЕЕ; const { esc } = О;
  const ГРУППЫ = [
    ['текст', 'Размер текста', [['обычный', 'Обычный'], ['крупнее', 'Крупнее'], ['самый', 'Самый крупный']], 'Все надписи растут вместе: текст Библии 18, 20 или 22,5 пикселя.'],
    ['тема', 'Тема', [['система', 'Как в системе'], ['light', 'Светлая'], ['dark', 'Тёмная']], ''],
    ['плотность', 'Плотность', [['обычная', 'Обычная'], ['плотная', 'Плотная']], 'Плотная — строки ниже, размер букв тот же. На телефоне кнопки не меньше 44 пикселей.'],
    ['слой', 'Показ', [['1', 'Для начинающих'], ['2', 'Для изучающих']], ''],
    ['писание', 'Текст Библии', [['сплошным', 'Сплошным текстом'], ['по стихам', 'Каждый стих с новой строки']], 'Номера стихов видны в обоих случаях.'],
    ['движение', 'Движение', [['система', 'Как в системе'], ['без', 'Без движения'], ['с', 'С движением']], ''],
    ['клавишаПоиска', 'Клавиша «/» — поиск', [['вкл', 'Включена'], ['выкл', 'Выключена']], ''],
  ];
  function группа([ключ, имя, варианты, пояснение]) {
    if (ключ === 'плотность' && !О.слой2()) return ''; // плотность предлагается во втором слое (08 § 3.4)
    return `<fieldset class="радио"><legend>${esc(имя)}</legend>${варианты.map(([v, п]) => `<label><input type="radio" name="${ключ}" value="${esc(v)}" ${String(О.настройки[ключ]) === v ? 'checked' : ''}> ${esc(п)}</label>`).join('')}${пояснение ? `<p class="т-адрес пояснение">${esc(пояснение)}</p>` : ''}</fieldset>`;
  }
  function отрисовать() {
    const в = О.настройки.возраст;
    document.getElementById('главное').innerHTML = `<div class="настройки">
      <h1 class="т-h1" id="h1" tabindex="-1" style="padding-top:var(--otstup-24)">Настройки</h1>
      <p class="т-интерфейс ч2">Настройки хранятся только на этом устройстве и никуда не отправляются.</p>
      ${ГРУППЫ.map(группа).join('')}
      <fieldset class="радио"><legend>Возраст</legend>
        <label><input type="radio" name="возраст-вид" value="нет" ${в === null ? 'checked' : ''}> Не указывать</label>
        <label><input type="radio" name="возраст-вид" value="число" ${в !== null ? 'checked' : ''}> Указать: <span class="скрыто">сколько вам лет</span></label>
        <p><label for="возраст-поле" class="т-интерфейс">Сколько вам лет</label> <input class="поле-числа" id="возраст-поле" type="number" min="1" max="120" value="${в ?? ''}"></p>
        <p class="т-адрес пояснение">Если вам меньше 13 лет, появятся подсказки для чтения со взрослым. Облик и истории от возраста не меняются.</p></fieldset>
      <h2 class="т-книга" id="заметки" style="margin-top:var(--otstup-32)">Мои заметки и закладки</h2>
      <p class="голос-мы">Заметки хранятся только на этом устройстве. Сохраните их в файл.</p>
      <p class="ряд-кнопок"><button class="кн" type="button" data-выгрузка="json">${О.значок('выгрузить')}${О.слой2() ? 'Заметки (JSON)' : 'Сохранить заметки в файл'}</button><button class="кн" type="button" data-выгрузка="csv">${О.значок('выгрузить')}${О.слой2() ? 'Таблица для Excel (CSV)' : 'Сохранить таблицу в файл'}</button></p>
    </div>`;
  }
  const ИМЕНА = { текст: 'Размер текста', тема: 'Тема', плотность: 'Плотность', слой: 'Показ', писание: 'Текст Библии', движение: 'Движение', клавишаПоиска: 'Клавиша «/»' };
  document.addEventListener('change', (e) => {
    const t = e.target;
    if (t.name && t.name in ИМЕНА) {
      О.настройки[t.name] = t.value; О.записать(О.настройки); О.применить();
      О.объявить(`${ИМЕНА[t.name]}: ${t.closest('label').textContent.trim()}`);
      if (t.name === 'слой') { const имя = t.name, v = t.value; отрисовать(); document.querySelector(`input[name="${имя}"][value="${v}"]`)?.focus(); }
    }
    if (t.name === 'возраст-вид' || t.id === 'возраст-поле') {
      const нет = document.querySelector('input[name="возраст-вид"][value="нет"]').checked && t.id !== 'возраст-поле';
      const v = document.getElementById('возраст-поле').value;
      О.настройки.возраст = нет || !v ? null : v; О.настройки.возрастСпрошен = true; О.записать(О.настройки);
      if (t.id === 'возраст-поле' && v) document.querySelector('input[name="возраст-вид"][value="число"]').checked = true;
      О.объявить(О.настройки.возраст ? `Возраст: ${О.настройки.возраст}` : 'Возраст не указан');
    }
  });
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-выгрузка]');
    if (!b) return;
    let заметки = []; try { заметки = JSON.parse(localStorage.getItem('лист-образец:заметки') || '[]'); } catch { /* пусто */ }
    const csv = b.dataset.выгрузка === 'csv';
    const тело = csv ? '﻿' + ['адрес;заметка;когда', ...заметки.map((з) => [з.адрес, з.текст, new Date(з.когда).toISOString()].map((x) => `"${String(x).replace(/"/g, '""')}"`).join(';'))].join('\r\n') : JSON.stringify({ формат: 'библия-наглядно/заметки', заметки }, null, 1);
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([тело], { type: csv ? 'text/csv' : 'application/json' }));
    a.download = `библия-наглядно_заметки_${new Date().toISOString().slice(0, 10)}.${csv ? 'csv' : 'json'}`;
    a.click();
    О.объявить(`Сохранено: заметок ${заметки.length}`);
  });
  document.addEventListener('DOMContentLoaded', () => {
    О.оболочка({ активный: 'Настройки', панель: new URLSearchParams(location.search).get('panel') !== '0' });
    document.title = 'Настройки — Библия наглядно';
    отрисовать();
  });
})();
